package dev.giljabi;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class WalkingSceneGateTest {
    private static final List<YoloDetector.Box> NONE=Collections.emptyList();
    private SceneSignature image(boolean shifted){int[] pixels=new int[192];for(int i=0;i<pixels.length;i++){int value=((i%16<8)^shifted)?55:185;pixels[i]=0xff000000|(value<<16)|(value<<8)|value;}return new SceneSignature(pixels);}
    private YoloDetector.Box chair(float center){return box(56,center-.1f,.58f,center+.1f,.96f);}
    private YoloDetector.Box box(int label,float left,float top,float right,float bottom){return new YoloDetector.Box(label,.91f,new float[]{left,top,right,bottom});}
    private void observe(WalkingSceneGate gate,long frame,long time,List<YoloDetector.Box> boxes){gate.observe(frame,image(false),boxes,time);}
    private WalkingSceneGate empty(){WalkingSceneGate gate=new WalkingSceneGate();gate.reset();observe(gate,1,0,NONE);WalkingSceneGate.Decision first=gate.decision(1);assertNotNull(first);gate.accepted(first);return gate;}
    private WalkingSceneGate chairScene(){WalkingSceneGate gate=new WalkingSceneGate();gate.reset();for(int i=1;i<=3;i++)observe(gate,i,(i-1)*200,Collections.singletonList(chair(.5f)));WalkingSceneGate.Decision initial=gate.decision(3);assertEquals(WalkingSceneGate.Reason.INITIAL,initial.reason);assertTrue(initial.stateKey.contains("seat:lower:path"));gate.accepted(initial);return gate;}
    @Test public void initialCanBeReviewedBeforeDetectorConfirmation(){WalkingSceneGate gate=new WalkingSceneGate();gate.reset();observe(gate,1,0,NONE);WalkingSceneGate.Decision first=gate.decision(1);assertEquals(WalkingSceneGate.Reason.INITIAL,first.reason);assertEquals(1,first.episode);assertEquals(0,first.observedAt);}
    @Test public void stationarySceneRemainsQuietInsideReviewWindow(){WalkingSceneGate gate=chairScene();for(int i=4;i<40;i++){observe(gate,i,i*200,Collections.singletonList(chair(.5f)));assertNull(gate.decision(i));}}
    @Test public void threeOfFiveEvidenceSurvivesDetectionFlicker(){WalkingSceneGate gate=empty();observe(gate,2,200,Collections.singletonList(chair(.5f)));observe(gate,3,400,NONE);observe(gate,4,600,Collections.singletonList(chair(.5f)));assertNull(gate.decision(4));observe(gate,5,800,NONE);observe(gate,6,1000,Collections.singletonList(chair(.5f)));WalkingSceneGate.Decision changed=gate.decision(6);assertEquals(WalkingSceneGate.Reason.PATH_CHANGE,changed.reason);assertTrue(changed.stateKey.contains("seat:lower:path"));}
    @Test public void singleFalsePositiveDoesNotBecomePathEvent(){WalkingSceneGate gate=empty();observe(gate,2,200,Collections.singletonList(chair(.5f)));for(int i=3;i<20;i++){observe(gate,i,i*200,NONE);assertNull(gate.decision(i));}}
    @Test public void tenSecondDropoutRetainsContextAndDoesNotReannounce(){WalkingSceneGate gate=chairScene();observe(gate,4,10400,NONE);assertNull(gate.decision(4));observe(gate,5,10600,Collections.singletonList(chair(.55f)));assertNull(gate.decision(5));assertTrue(gate.relevant(new WalkingSceneGate.Decision(1,3,400,1,image(false),Collections.singletonList(chair(.5f)),WalkingSceneGate.Reason.INITIAL,"","seat:lower:path")));}
    @Test public void countsDoNotChangeSemanticCorridorState(){WalkingSceneGate gate=new WalkingSceneGate();gate.reset();List<YoloDetector.Box> two=Arrays.asList(chair(.40f),chair(.60f));for(int i=1;i<=3;i++)observe(gate,i,i*200,two);WalkingSceneGate.Decision first=gate.decision(3);gate.accepted(first);String key=first.stateKey;for(int i=4;i<=6;i++){observe(gate,i,i*200,Collections.singletonList(chair(.50f)));assertNull(gate.decision(i));}List<YoloDetector.Box> three=Arrays.asList(chair(.35f),chair(.50f),chair(.65f));for(int i=7;i<=11;i++){observe(gate,i,i*200,three);assertNull(gate.decision(i));}assertTrue(key.contains("seat:lower:path"));}
    @Test public void sideChairDoesNotCreatePathEvent(){WalkingSceneGate gate=empty();for(int i=2;i<=10;i++){observe(gate,i,i*200,Collections.singletonList(box(56,.01f,.50f,.20f,.95f)));assertNull(gate.decision(i));}}
    @Test public void sameObjectMovingAcrossImageIsNotANewSemanticScene(){WalkingSceneGate gate=chairScene();float[] centers={.35f,.58f,.68f,.38f,.55f,.30f,.62f};for(int i=0;i<centers.length;i++){observe(gate,i+4,800+i*200,Collections.singletonList(chair(centers[i])));assertNull(gate.decision(i+4));}}
    @Test public void rawPixelChangesFromCaneSweepDoNotTriggerSpeechStateChange(){WalkingSceneGate gate=chairScene();for(int i=4;i<=15;i++){gate.observe(i,image(i%2==0),Collections.singletonList(chair(i%2==0?.40f:.60f)),i*200);assertNull(gate.decision(i));}}
    @Test public void upperCentralCueIsAllowedWithoutMetricHeightOrDistance(){WalkingSceneGate gate=empty();for(int i=2;i<=4;i++)observe(gate,i,i*200,Collections.singletonList(box(11,.40f,.03f,.60f,.26f)));WalkingSceneGate.Decision changed=gate.decision(4);assertEquals(WalkingSceneGate.Reason.PATH_CHANGE,changed.reason);assertTrue(changed.stateKey.contains("upper:path"));assertTrue(changed.context.contains("distance_metres=unavailable"));assertTrue(changed.context.contains("image_upper_band_does_not_measure_head_height"));assertTrue(changed.context.contains("camera_mount=white_cane_sweep"));}
    @Test public void aNewPathTypeInvalidatesPreviousDecision(){WalkingSceneGate gate=chairScene();observe(gate,4,800,Collections.singletonList(chair(.5f)));WalkingSceneGate.Decision before=new WalkingSceneGate.Decision(1,4,800,1,image(false),Collections.singletonList(chair(.5f)),WalkingSceneGate.Reason.VISUAL_REVIEW,"","seat:lower:path");for(int i=5;i<=7;i++)observe(gate,i,i*200,Arrays.asList(chair(.5f),box(0,.35f,.18f,.65f,.88f)));assertFalse(gate.relevant(before));assertEquals(WalkingSceneGate.Reason.PATH_CHANGE,gate.decision(7).reason);}
    @Test public void retainedObservationIsMarkedMissingAndOld(){WalkingSceneGate gate=chairScene();observe(gate,4,12400,NONE);WalkingSceneGate.Decision review=gate.decision(4);assertEquals(WalkingSceneGate.Reason.VISUAL_REVIEW,review.reason);assertTrue(review.context.contains("currently_visible=false"));assertTrue(review.context.contains("age_ms=12000"));assertTrue(review.context.contains("retained_only=true"));gate.accepted(review);observe(gate,5,12600,NONE);WalkingSceneGate.Decision removed=gate.decision(5);assertNotNull(removed);assertFalse(gate.relevant(review));}
    @Test public void visualReviewIsBoundedAndDoesNotRequirePixelMotion(){WalkingSceneGate gate=empty();observe(gate,2,11999,NONE);assertNull(gate.decision(2));observe(gate,3,12000,NONE);WalkingSceneGate.Decision review=gate.decision(3);assertEquals(WalkingSceneGate.Reason.VISUAL_REVIEW,review.reason);gate.accepted(review);observe(gate,4,12100,NONE);assertNull(gate.decision(4));}
    @Test public void newEpisodeNeedsTrackExpiryAndConfirmedClearInterval(){WalkingSceneGate gate=chairScene();observe(gate,4,10000,NONE);assertNull(gate.decision(4));observe(gate,5,12401,NONE);WalkingSceneGate.Decision firstClear=gate.decision(5);assertEquals(1,firstClear.episode);gate.accepted(firstClear);observe(gate,6,13500,NONE);observe(gate,7,15500,NONE);for(int i=8;i<=10;i++)observe(gate,i,16000+(i-8)*200,Collections.singletonList(chair(.5f)));WalkingSceneGate.Decision later=gate.decision(10);assertEquals(2,later.episode);assertEquals(WalkingSceneGate.Reason.PATH_CHANGE,later.reason);assertEquals("seat:lower:path",later.stateKey);}
    @Test public void pendingVisibleCuePreventsPrematureClearEpisode(){WalkingSceneGate gate=chairScene();observe(gate,4,12401,NONE);WalkingSceneGate.Decision clear=gate.decision(4);gate.accepted(clear);observe(gate,5,15000,NONE);observe(gate,6,15600,Collections.singletonList(chair(.5f)));observe(gate,7,15800,Collections.singletonList(chair(.5f)));observe(gate,8,16000,Collections.singletonList(chair(.5f)));assertEquals(1,gate.decision(8).episode);}
    @Test public void reconnectDoesNotForgetAnAnnouncedScene(){WalkingSceneGate gate=chairScene();gate.reconnect();for(int i=10;i<=12;i++){observe(gate,i,1000+(i-10)*200,Collections.singletonList(chair(.5f)));assertNull(gate.decision(i));}}
    @Test public void resetRejectsOldProviderResults(){WalkingSceneGate gate=empty();observe(gate,2,12000,NONE);WalkingSceneGate.Decision old=gate.decision(2);gate.reset();observe(gate,3,13000,NONE);gate.accepted(old);assertFalse(gate.relevant(old));assertEquals(WalkingSceneGate.Reason.INITIAL,gate.decision(3).reason);}
    @Test public void decisionOwnsCopyOfCurrentBoxes(){WalkingSceneGate gate=new WalkingSceneGate();gate.reset();YoloDetector.Box chair=chair(.5f);observe(gate,1,0,Collections.singletonList(chair));WalkingSceneGate.Decision decision=gate.decision(1);chair.xy[0]=0;assertEquals(.4f,decision.boxes.get(0).xy[0],.0001f);assertThrows(UnsupportedOperationException.class,()->decision.boxes.clear());}
    @Test public void blankFramesDoNotPromoteHallucinatedDetectorBoxes(){WalkingSceneGate gate=empty();int[] black=new int[192];Arrays.fill(black,0xff000000);for(int i=2;i<7;i++)gate.observe(i,new SceneSignature(black),Collections.singletonList(chair(.5f)),i*200);assertNull(gate.decision(6));}
    @Test public void classFlickerWithinSameFamilyKeepsPathState(){WalkingSceneGate gate=chairScene();for(int i=4;i<=10;i++){YoloDetector.Box chair=chair(.5f);observe(gate,i,i*200,Collections.singletonList(new YoloDetector.Box(i%2==0?13:56,.9f,chair.xy)));assertNull(gate.decision(i));}}
    @Test public void explicitUnchangedReviewsDoNotCreatePathEvents(){WalkingSceneGate gate=chairScene();String key="seat:lower:path";for(int i=4;i<=12;i++){observe(gate,i,i*200,Collections.singletonList(chair(.5f)));WalkingSceneGate.Decision review=gate.review(i);assertNotNull(review);assertEquals(WalkingSceneGate.Reason.VISUAL_REVIEW,review.reason);assertEquals(key,review.stateKey);assertEquals(1,review.episode);assertEquals(i,review.sequence);assertNull(gate.decision(i));}}
    @Test public void explicitReviewDoesNotConsumeInitialOrPendingPathChange(){WalkingSceneGate gate=new WalkingSceneGate();gate.reset();observe(gate,1,0,NONE);assertEquals(WalkingSceneGate.Reason.VISUAL_REVIEW,gate.review(1).reason);assertEquals(WalkingSceneGate.Reason.INITIAL,gate.decision(1).reason);gate.accepted(gate.decision(1));for(int i=2;i<=4;i++)observe(gate,i,i*200,Collections.singletonList(chair(.5f)));assertEquals(WalkingSceneGate.Reason.PATH_CHANGE,gate.decision(4).reason);gate.review(4);assertEquals(WalkingSceneGate.Reason.PATH_CHANGE,gate.decision(4).reason);}
    @Test public void explicitReviewNeedsTheLatestAvailableFrame(){WalkingSceneGate gate=new WalkingSceneGate();gate.reset();assertNull(gate.review(1));observe(gate,1,0,NONE);assertNull(gate.review(0));assertNotNull(gate.review(1));gate.reconnect();assertNull(gate.review(1));}

}
